# scripts/run-gates.map — path-to-gate map for scripts/run-gates.sh (a local convenience; CI runs every gate).
# Rows are <path glob><TAB><gate command>. The first row whose glob matches a path decides for that path;
# every row with that exact glob applies. A glob uses shell case patterns (* also matches /). A gate
# command is written as the workflow writes it, with optional leading VAR=value words (the env of the
# workflow step) and {BASE} for the base ref. `@all` as the gate selects every gate. A path that matches no
# row selects every gate, so list a path only when its gates are known. `@skip<TAB>command<TAB>reason`
# names a workflow command that is not a standalone gate. scripts/run-gates.sh, this file and .github/*
# select every gate in the script itself.
# Keep this in step with .github/workflows/validate-skills.yml: scripts/run-gates.test.sh fails when a
# workflow command is missing here, when a gate here is not in the workflow or when a script is missing.

# check-fences.sh --has-mappings answers "are there mappings" with exit 0 or 1 and is the guard of the --from-templates gate
@skip	bash scripts/check-fences.sh --has-mappings	exit 1 is a normal answer, not a failure

# Skills. Template trees and scaffold, migrate, cleanup and review leaves feed nearly every gate.
skills/*template*	@all
skills/scaffold/*	@all
skills/migrate/*	@all
skills/cleanup/*	@all
skills/review/*	@all
skills/*.md	bash scripts/lint-skills.sh skills/
skills/*.md	bash scripts/lint-skills.test.sh
skills/*.md	bash scripts/lint-skills-pool.test.sh
skills/*.md	STRICT_DOC_SYNC=1 bash scripts/validate-manifest.sh .claude-plugin
skills/*.md	bash scripts/check-doc-sync.sh
skills/*.md	bash scripts/check-versions.sh
skills/*.md	bash scripts/count-load.sh --base origin/main
skills/*.md	bash scripts/count-load.sh --summary all --base origin/main
skills/*.md	bash scripts/check-fences.sh
skills/*.md	bash scripts/check-fences.sh --from-templates
skills/*.md	bash scripts/check-fences.test.sh
skills/*.md	bash scripts/check-fences-frozen.test.sh
skills/*.md	bash scripts/check-golden.sh
skills/*.md	bash scripts/check-golden.sh --from-templates
skills/*.md	bash scripts/check-template-comments.sh
skills/*.md	bash scripts/test-template-copy.sh
skills/*	@all

